// WP-1.4 visibility buffer: see include/fuse/renderer/visbuffer/visbuffer.hpp.
#include <fuse/renderer/visbuffer/visbuffer.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <cstring>
#include <initializer_list>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_wp14.cmake from shaders/visbuffer/*.{slang,vert,frag,comp}:
// kVis<Kernel><Slang|Glsl>Spv and FUSE_VISBUFFER_{SLANG,GLSL} when every kernel of a language exists.
#include "visbuffer_spv.h"
#endif

namespace fuse::renderer::visbuffer {

namespace {
constexpr u32 kPushBytes = 96u;
static_assert(sizeof(VisRasterPush) == kPushBytes && sizeof(VisDecodePush) == kPushBytes, "push sizes");

#if defined(FUSE_VULKAN_BACKEND)
constexpr u32 kGroup = 8u; // vis64 / vis_decode workgroups are 8 x 8

struct Code {
    const u32* words = nullptr;
    usize bytes = 0;
};
template <usize N>
Code code(const u32 (&spv)[N]) {
    return Code{spv, sizeof(spv)};
}
struct KernelSet {
    Code rasterVs, rasterFs, atomicFsImage, atomicFsBuffer, vis64Image, vis64Buffer, decode;
};
#endif
} // namespace

VisCapabilities queryVisCapabilities(const VulkanDevice* device) {
    VisCapabilities c{};
#if defined(FUSE_VULKAN_BACKEND)
    if (device == nullptr || !device->isValid()) {
        return c;
    }
    const VulkanDeviceInfo& info = device->info();
    const RendererCaps& caps = info.caps;
    if (!caps.bufferDeviceAddress || !caps.drawIndirectCount || !info.dynamicRendering) {
        c.rasterReason = "bufferDeviceAddress / drawIndirectCount / dynamicRendering missing";
    } else if (!info.geometryShader) {
        c.rasterReason = "geometryShader feature not enabled (PrimitiveId in the fragment stage)";
    } else {
        c.raster = true;
        c.rasterReason = "ok";
    }
    if (!c.raster) {
        c.atomicReason = "raster path unavailable";
        return c;
    }
    if (!info.fragmentStoresAndAtomics || !caps.shaderInt64) {
        c.atomicReason = "fragmentStoresAndAtomics / shaderInt64 not enabled";
        return c;
    }
    c.atomicBuffer = caps.shaderBufferInt64Atomics;
    if (caps.shaderImageInt64Atomics) {
        VkFormatProperties props{};
        vkGetPhysicalDeviceFormatProperties(static_cast<VkPhysicalDevice>(device->nativePhysicalDevice()), VK_FORMAT_R64_UINT,
                                            &props);
        const VkFormatFeatureFlags need = VK_FORMAT_FEATURE_STORAGE_IMAGE_BIT | VK_FORMAT_FEATURE_STORAGE_IMAGE_ATOMIC_BIT;
        c.atomicImage = (props.optimalTilingFeatures & need) == need;
    }
    c.atomicReason = (c.atomicBuffer || c.atomicImage) ? "ok" : "no 64-bit buffer or image atomics";
#else
    (void)device;
    c.rasterReason = "stub backend";
    c.atomicReason = "stub backend";
#endif
    return c;
}

VisBuffer::~VisBuffer() { destroy(); }

bool VisBuffer::init(const VisBufferDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.allocator == nullptr || desc.bindless == nullptr) {
        return false;
    }
    const VisCapabilities caps = queryVisCapabilities(desc.device);
    if (!caps.raster) {
        return false;
    }
    if (desc.mode == VisMode::Atomic64) {
        switch (desc.atomicTarget) {
        case VisAtomicTarget::Image:
            if (!caps.atomicImage) {
                return false;
            }
            m_atomicTarget = VisAtomicTarget::Image;
            break;
        case VisAtomicTarget::Buffer:
            if (!caps.atomicBuffer) {
                return false;
            }
            m_atomicTarget = VisAtomicTarget::Buffer;
            break;
        case VisAtomicTarget::Auto:
            if (!caps.atomicImage && !caps.atomicBuffer) {
                return false;
            }
            m_atomicTarget = caps.atomicImage ? VisAtomicTarget::Image : VisAtomicTarget::Buffer;
            break;
        }
    }
    m_retired.reserve(4);
    m_initialized = true; // destroy() releases partial state from here on
    if (!createPipelines() || (desc.width > 0u && desc.height > 0u && !resize(desc.width, desc.height))) {
        destroy();
        return false;
    }
    m_stats.targetRebuilds = desc.width > 0u ? 1u : 0u;
    return true;
#else
    return false;
#endif
}

void VisBuffer::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    destroyTargets(m_targets);
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    for (void* pipeline : {m_rasterPipeline, m_atomicPipeline, m_vis64Pipeline, m_decodePipeline}) {
        if (pipeline != nullptr) {
            vkDestroyPipeline(device, static_cast<VkPipeline>(pipeline), nullptr);
        }
    }
    for (void* layout : {m_graphicsLayout, m_computeLayout}) {
        if (layout != nullptr) {
            vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(layout), nullptr);
        }
    }
#endif
    m_rasterPipeline = m_atomicPipeline = m_vis64Pipeline = m_decodePipeline = nullptr;
    m_graphicsLayout = m_computeLayout = nullptr;
    m_targets = Targets{};
    m_retired.clear();
    m_width = m_height = 0;
    m_drawCount = m_vis64Count = m_decodeCount = 0;
    m_language = "none";
    m_stats = VisStats{};
    m_initialized = false;
}

bool VisBuffer::createPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    KernelSet k{};
    bool found = false;
#if defined(FUSE_VISBUFFER_SLANG)
    if (m_desc.language == VisKernelLanguage::Auto || m_desc.language == VisKernelLanguage::Slang) {
        k = KernelSet{code(kVisRasterVsSlangSpv),  code(kVisRasterFsSlangSpv), code(kVisAtomicFsImageSlangSpv),
                      code(kVisAtomicFsBufferSlangSpv), code(kVisVis64ImageSlangSpv), code(kVisVis64BufferSlangSpv),
                      code(kVisDecodeSlangSpv)};
        m_language = "slang";
        found = true;
    }
#endif
#if defined(FUSE_VISBUFFER_GLSL)
    if (!found && (m_desc.language == VisKernelLanguage::Auto || m_desc.language == VisKernelLanguage::Glsl)) {
        k = KernelSet{code(kVisRasterVsGlslSpv),  code(kVisRasterFsGlslSpv), code(kVisAtomicFsImageGlslSpv),
                      code(kVisAtomicFsBufferGlslSpv), code(kVisVis64ImageGlslSpv), code(kVisVis64BufferGlslSpv),
                      code(kVisDecodeGlslSpv)};
        m_language = "glsl";
        found = true;
    }
#endif
    if (!found) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    auto makeLayout = [&](VkShaderStageFlags stages, void*& out) {
        VkPushConstantRange range{stages, 0, kPushBytes};
        VkPipelineLayoutCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
        info.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
        info.pSetLayouts = &setLayout;
        info.pushConstantRangeCount = 1;
        info.pPushConstantRanges = &range;
        VkPipelineLayout layout = VK_NULL_HANDLE;
        const bool ok = vkCreatePipelineLayout(device, &info, nullptr, &layout) == VK_SUCCESS;
        out = layout;
        return ok;
    };
    if (!makeLayout(VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, m_graphicsLayout) ||
        !makeLayout(VK_SHADER_STAGE_COMPUTE_BIT, m_computeLayout)) {
        return false;
    }
    auto module = [&](const Code& c) {
        VkShaderModuleCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        info.codeSize = c.bytes;
        info.pCode = c.words;
        VkShaderModule m = VK_NULL_HANDLE;
        vkCreateShaderModule(device, &info, nullptr, &m);
        return m;
    };
    const VkPipelineCreateFlags createFlags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    auto compute = [&](const Code& c, void*& out) {
        VkShaderModule m = module(c);
        if (m == VK_NULL_HANDLE) {
            return false;
        }
        VkComputePipelineCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
        info.flags = createFlags;
        info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        info.stage.module = m;
        info.stage.pName = "main";
        info.layout = static_cast<VkPipelineLayout>(m_computeLayout);
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
        vkDestroyShaderModule(device, m, nullptr);
        out = pipeline;
        return result == VK_SUCCESS;
    };
    // Raster (R32G32 + D32) or atomic (no attachments) draw pipeline; no vertex input (VPOS is pulled).
    auto graphics = [&](const Code& fsCode, bool atomic, void*& out) {
        VkShaderModule vs = module(k.rasterVs);
        VkShaderModule fs = module(fsCode);
        if (vs == VK_NULL_HANDLE || fs == VK_NULL_HANDLE) {
            vkDestroyShaderModule(device, vs, nullptr);
            vkDestroyShaderModule(device, fs, nullptr);
            return false;
        }
        VkPipelineShaderStageCreateInfo stages[2]{};
        stages[0].sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        stages[0].stage = VK_SHADER_STAGE_VERTEX_BIT;
        stages[0].module = vs;
        stages[0].pName = "main";
        stages[1].sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        stages[1].stage = VK_SHADER_STAGE_FRAGMENT_BIT;
        stages[1].module = fs;
        stages[1].pName = "main";
        VkPipelineVertexInputStateCreateInfo vertexInput{};
        vertexInput.sType = VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO;
        VkPipelineInputAssemblyStateCreateInfo assembly{};
        assembly.sType = VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO;
        assembly.topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST;
        VkPipelineViewportStateCreateInfo viewport{};
        viewport.sType = VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO;
        viewport.viewportCount = 1;
        viewport.scissorCount = 1;
        VkPipelineRasterizationStateCreateInfo rasterization{};
        rasterization.sType = VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO;
        rasterization.polygonMode = VK_POLYGON_MODE_FILL;
        rasterization.cullMode = VK_CULL_MODE_NONE; // two-sided until materials carry a cull flag
        rasterization.lineWidth = 1.f;
        VkPipelineMultisampleStateCreateInfo multisample{};
        multisample.sType = VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO;
        multisample.rasterizationSamples = VK_SAMPLE_COUNT_1_BIT;
        VkPipelineDepthStencilStateCreateInfo depth{};
        depth.sType = VK_STRUCTURE_TYPE_PIPELINE_DEPTH_STENCIL_STATE_CREATE_INFO;
        depth.depthTestEnable = atomic ? VK_FALSE : VK_TRUE;
        depth.depthWriteEnable = atomic ? VK_FALSE : VK_TRUE;
        depth.depthCompareOp = VK_COMPARE_OP_LESS;
        VkPipelineColorBlendAttachmentState blendAttachment{};
        blendAttachment.colorWriteMask = VK_COLOR_COMPONENT_R_BIT | VK_COLOR_COMPONENT_G_BIT;
        VkPipelineColorBlendStateCreateInfo blend{};
        blend.sType = VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO;
        blend.attachmentCount = atomic ? 0u : 1u;
        blend.pAttachments = atomic ? nullptr : &blendAttachment;
        const VkDynamicState dynamics[2] = {VK_DYNAMIC_STATE_VIEWPORT, VK_DYNAMIC_STATE_SCISSOR};
        VkPipelineDynamicStateCreateInfo dynamic{};
        dynamic.sType = VK_STRUCTURE_TYPE_PIPELINE_DYNAMIC_STATE_CREATE_INFO;
        dynamic.dynamicStateCount = 2;
        dynamic.pDynamicStates = dynamics;
        const VkFormat colorFormat = static_cast<VkFormat>(kVisRasterFormat);
        VkPipelineRenderingCreateInfo rendering{};
        rendering.sType = VK_STRUCTURE_TYPE_PIPELINE_RENDERING_CREATE_INFO;
        rendering.colorAttachmentCount = atomic ? 0u : 1u;
        rendering.pColorAttachmentFormats = atomic ? nullptr : &colorFormat;
        rendering.depthAttachmentFormat = atomic ? VK_FORMAT_UNDEFINED : static_cast<VkFormat>(kVisDepthFormat);
        VkGraphicsPipelineCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO;
        info.pNext = &rendering;
        info.flags = createFlags;
        info.stageCount = 2;
        info.pStages = stages;
        info.pVertexInputState = &vertexInput;
        info.pInputAssemblyState = &assembly;
        info.pViewportState = &viewport;
        info.pRasterizationState = &rasterization;
        info.pMultisampleState = &multisample;
        info.pDepthStencilState = &depth;
        info.pColorBlendState = &blend;
        info.pDynamicState = &dynamic;
        info.layout = static_cast<VkPipelineLayout>(m_graphicsLayout);
        VkPipeline pipeline = VK_NULL_HANDLE;
        const VkResult result = vkCreateGraphicsPipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
        vkDestroyShaderModule(device, vs, nullptr);
        vkDestroyShaderModule(device, fs, nullptr);
        out = pipeline;
        return result == VK_SUCCESS;
    };
    if (!compute(k.decode, m_decodePipeline)) {
        return false;
    }
    if (m_desc.mode == VisMode::Raster) {
        return graphics(k.rasterFs, false, m_rasterPipeline);
    }
    const bool image = m_atomicTarget == VisAtomicTarget::Image;
    return graphics(image ? k.atomicFsImage : k.atomicFsBuffer, true, m_atomicPipeline) &&
           compute(image ? k.vis64Image : k.vis64Buffer, m_vis64Pipeline);
#else
    return false;
#endif
}

bool VisBuffer::createTargets(Targets& t, u32 width, u32 height) {
    t = Targets{};
    const bool atomic = m_desc.mode == VisMode::Atomic64;
    auto usage = [](std::initializer_list<ImageUsage> bits) {
        u32 u = 0;
        for (const ImageUsage b : bits) {
            u |= static_cast<u32>(b);
        }
        return static_cast<ImageUsage>(u);
    };
    TextureDesc vis{};
    vis.width = width;
    vis.height = height;
    vis.format = static_cast<GpuFormat>(kVisRasterFormat);
    vis.usage = atomic ? usage({ImageUsage::Storage, ImageUsage::TransferSrc})
                       : usage({ImageUsage::ColorAttachment, ImageUsage::Storage, ImageUsage::TransferSrc});
    vis.name = "visbuffer.vis";
    TextureDesc depth{};
    depth.width = width;
    depth.height = height;
    depth.format = atomic ? GpuFormat::R32Sfloat : GpuFormat::D32Sfloat;
    depth.usage = atomic ? usage({ImageUsage::Storage, ImageUsage::Sampled, ImageUsage::TransferSrc})
                         : usage({ImageUsage::DepthStencilAttachment, ImageUsage::Sampled, ImageUsage::TransferSrc});
    depth.name = atomic ? "visbuffer.depth_export" : "visbuffer.depth";
    if (!m_desc.allocator->createImage(vis, t.vis) || !m_desc.allocator->createImage(depth, t.depth)) {
        destroyTargets(t);
        return false;
    }
    t.visStorage = m_desc.bindless->registerTextureSlot(t.vis, true);
    t.depthSampled = m_desc.bindless->registerTextureSlot(t.depth, false);
    bool ok = t.visStorage.isValid() && t.depthSampled.isValid();
    if (atomic) {
        t.depthStorage = m_desc.bindless->registerTextureSlot(t.depth, true);
        ok = ok && t.depthStorage.isValid();
        if (m_atomicTarget == VisAtomicTarget::Image) {
            TextureDesc words{};
            words.width = width;
            words.height = height;
            words.format = static_cast<GpuFormat>(kVis64ImageFormat);
            words.usage = usage({ImageUsage::Storage, ImageUsage::TransferSrc});
            words.name = "visbuffer.vis64";
            ok = ok && m_desc.allocator->createImage(words, t.image64);
            if (ok) {
                t.target64 = m_desc.bindless->registerTextureSlot(t.image64, true);
            }
        } else {
            BufferDesc words{};
            words.size = static_cast<usize>(width) * height * sizeof(u64);
            words.usage = static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) |
                                                   static_cast<u32>(BufferUsage::TransferSrc) |
                                                   static_cast<u32>(BufferUsage::ShaderDeviceAddress));
            words.memoryUsage = MemoryUsage::GpuOnly;
            words.name = "visbuffer.vis64";
            ok = ok && m_desc.allocator->createBuffer(words, t.buffer64);
            if (ok) {
                t.target64 = m_desc.bindless->registerBufferSlot(t.buffer64, false);
            }
        }
        ok = ok && t.target64.isValid();
    }
    if (!ok) {
        destroyTargets(t);
    }
    return ok;
}

void VisBuffer::destroyTargets(Targets& t) {
    for (BindlessSlotHandle* slot : {&t.visStorage, &t.depthSampled, &t.depthStorage, &t.target64}) {
        if (slot->isValid()) {
            m_desc.bindless->unregisterSlot(*slot);
        }
    }
    for (Texture* image : {&t.vis, &t.depth, &t.image64}) {
        if (image->image != nullptr) {
            m_desc.allocator->destroyImage(*image);
        }
    }
    if (t.buffer64.handle != nullptr) {
        m_desc.allocator->destroyBuffer(t.buffer64);
    }
    t = Targets{};
}

bool VisBuffer::resize(u32 width, u32 height) {
    if (!m_initialized || width == 0u || height == 0u) {
        return false;
    }
    if (width == m_width && height == m_height && m_targets.vis.image != nullptr) {
        return true;
    }
    Targets fresh{};
    if (!createTargets(fresh, width, height)) {
        return false;
    }
    if (m_targets.vis.image != nullptr) {
        m_retired.push_back(Retired{m_targets, m_frameSerial});
        ++m_stats.retired;
    }
    m_targets = fresh;
    m_width = width;
    m_height = height;
    ++m_stats.targetRebuilds;
    return true;
}

u32 VisBuffer::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    usize keep = 0;
    for (usize i = 0; i < m_retired.size(); ++i) {
        if (m_retired[i].serial > completedSerial) {
            m_retired[keep++] = m_retired[i];
            continue;
        }
        destroyTargets(m_retired[i].targets);
        ++collected;
    }
    m_retired.resize(keep);
    m_stats.retired = m_stats.retired >= collected ? m_stats.retired - collected : 0u;
    return collected;
}

u32 VisBuffer::depthSampledHandle() const {
    return m_targets.depthSampled.isValid() ? m_desc.bindless->shaderHandle(m_targets.depthSampled) : 0u;
}

u32 VisBuffer::target64Handle() const {
    return m_targets.target64.isValid() ? m_desc.bindless->shaderHandle(m_targets.target64) : 0u;
}

u32 VisBuffer::visStorageHandle() const {
    return m_targets.visStorage.isValid() ? m_desc.bindless->shaderHandle(m_targets.visStorage) : 0u;
}

bool VisBuffer::beginFrame(u64 frameSerial, const f32 viewProj[16], u32 sceneHandle, u32 instanceHighWater) {
    if (!m_initialized || m_targets.vis.image == nullptr) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_drawCount = 0;
    m_vis64Count = 0;
    m_decodeCount = 0;
    m_stats.drawPasses = 0;
    VisRasterPush& p = m_rasterPush;
    std::memcpy(p.viewProj, viewProj, sizeof(p.viewProj));
    p.scene = sceneHandle;
    p.target64 = m_targets.target64.isValid() ? m_desc.bindless->shaderHandle(m_targets.target64) : 0u;
    p.width = m_width;
    p.height = m_height;
    m_stats.instanceLimitExceeded = m_desc.mode == VisMode::Atomic64 && instanceHighWater > kVis64MaxInstances;
    return !m_stats.instanceLimitExceeded;
}

VisGraphRefs VisBuffer::importInto(rg::Graph& graph) {
    VisGraphRefs refs{};
    if (!m_initialized || m_targets.vis.image == nullptr) {
        return refs;
    }
    auto image = [&](Texture& tex, u32 format, u32& layout, u8& queue, const char* name) {
        rg::ImportedImage i{};
        i.image = tex.image;
        i.view = tex.view;
        i.format = format;
        i.width = m_width;
        i.height = m_height;
        i.initialLayout = layout;
        i.initialQueue = queue;
        i.layoutTracker = &layout;
        i.queueTracker = &queue;
        i.name = name;
        return graph.importImage(i);
    };
    const bool atomic = m_desc.mode == VisMode::Atomic64;
    refs.vis = image(m_targets.vis, kVisRasterFormat, m_targets.visLayout, m_targets.visQueue, "visbuffer.vis");
    refs.depth = image(m_targets.depth, atomic ? kVisExportDepthFormat : kVisDepthFormat, m_targets.depthLayout,
                       m_targets.depthQueue, atomic ? "visbuffer.depth_export" : "visbuffer.depth");
    if (m_targets.image64.image != nullptr) {
        refs.image64 = image(m_targets.image64, kVis64ImageFormat, m_targets.image64Layout, m_targets.image64Queue,
                             "visbuffer.vis64");
    }
    if (m_targets.buffer64.handle != nullptr) {
        refs.buffer64 = graph.importBuffer(rg::ImportedBuffer{m_targets.buffer64.handle, m_targets.buffer64.desc.size,
                                                              m_targets.buffer64Queue, &m_targets.buffer64Queue,
                                                              "visbuffer.vis64"});
    }
    return refs;
}

void VisBuffer::addVis64Pass(rg::Graph& graph, const VisGraphRefs& refs, u32 mode) {
    if (m_vis64Count >= kMaxVis64Passes) {
        return;
    }
    Vis64Record& r = m_vis64[m_vis64Count++];
    r.self = this;
    r.push = Vis64Push{};
    r.push.target64 = m_rasterPush.target64;
    r.push.vis = m_desc.bindless->shaderHandle(m_targets.visStorage);
    r.push.depth = m_desc.bindless->shaderHandle(m_targets.depthStorage);
    r.push.width = m_width;
    r.push.height = m_height;
    r.push.mode = mode;
    const bool clear = mode == kVis64ModeClear;
    rg::PassBuilder pass = graph.addPass(clear ? "vis.clear" : "vis.export", &VisBuffer::recordVis64, &r);
    const rg::Access words = clear ? rg::Access::StorageWrite : rg::Access::StorageRead;
    if (refs.image64.valid()) {
        pass.use(refs.image64, words, {}, rg::kStageCompute);
    }
    if (refs.buffer64.valid()) {
        pass.use(refs.buffer64, words, {}, rg::kStageCompute);
    }
    if (!clear) {
        pass.use(refs.vis, rg::Access::StorageWrite, {}, rg::kStageCompute)
            .use(refs.depth, rg::Access::StorageWrite, {}, rg::kStageCompute);
    }
}

void VisBuffer::addDraw(rg::Graph& graph, const VisGraphRefs& refs, const gpu_scene::GpuSceneGraphRefs& scene,
                        const culling::InstanceCuller& culler, const culling::CullGraphRefs& cullRefs,
                        culling::CullPhase phase, bool clear) {
    if (!m_initialized || !refs.vis.valid() || m_drawCount >= kMaxDraws) {
        return;
    }
    const bool atomic = m_desc.mode == VisMode::Atomic64;
    if (atomic && clear) {
        addVis64Pass(graph, refs, kVis64ModeClear);
    }
    DrawRecord& r = m_draws[m_drawCount++];
    ++m_stats.drawPasses;
    r.self = this;
    r.culler = &culler;
    r.phase = phase;
    r.vis = refs.vis;
    r.depth = refs.depth;
    r.indices = scene.indices;
    r.clear = clear;
    rg::PassBuilder pass =
        graph.addPass(phase == culling::CullPhase::Phase1 ? "vis.phase1" : "vis.phase2", &VisBuffer::recordDraw, &r);
    culler.useDraws(pass, cullRefs, phase);
    gpu_scene::GpuScene::useAll(pass, scene, rg::Access::StorageRead, rg::kStageVertex);
    if (scene.indices.valid()) {
        pass.use(scene.indices, rg::Access::IndexRead);
    }
    if (atomic) {
        if (refs.image64.valid()) {
            pass.use(refs.image64, rg::Access::StorageReadWrite, {}, rg::kStageFragment);
        }
        if (refs.buffer64.valid()) {
            pass.use(refs.buffer64, rg::Access::StorageReadWrite, {}, rg::kStageFragment);
        }
    } else {
        pass.use(refs.vis, rg::Access::ColorAttachmentWrite).use(refs.depth, rg::Access::DepthAttachmentWrite);
    }
}

void VisBuffer::addExport(rg::Graph& graph, const VisGraphRefs& refs) {
    if (m_initialized && m_desc.mode == VisMode::Atomic64 && refs.vis.valid()) {
        addVis64Pass(graph, refs, kVis64ModeExport);
    }
}

void VisBuffer::addClear(rg::Graph& graph, const VisGraphRefs& refs) {
    if (m_initialized && m_desc.mode == VisMode::Atomic64 && refs.vis.valid()) {
        addVis64Pass(graph, refs, kVis64ModeClear);
    }
}

void VisBuffer::addCulledFrame(rg::Graph& graph, const VisGraphRefs& refs, const gpu_scene::GpuSceneGraphRefs& scene,
                               u32 sceneHandle, culling::InstanceCuller& culler, const culling::CullGraphRefs& cullRefs) {
    culler.addPhase1(graph, cullRefs, scene, sceneHandle);
    addDraw(graph, refs, scene, culler, cullRefs, culling::CullPhase::Phase1, true);
    addExport(graph, refs);
    culler.addHizBuild(graph, cullRefs, refs.depth, depthSampledHandle());
    culler.addPhase2(graph, cullRefs, scene, sceneHandle);
    addDraw(graph, refs, scene, culler, cullRefs, culling::CullPhase::Phase2, false);
    addExport(graph, refs);
    culler.addHizBuild(graph, cullRefs, refs.depth, depthSampledHandle());
}

void VisBuffer::addDecode(rg::Graph& graph, const VisGraphRefs& refs, const gpu_scene::GpuSceneGraphRefs& scene,
                          rg::BufferRef out, u64 outAddress) {
    if (!m_initialized || !refs.vis.valid() || m_decodeCount >= kMaxDecodes) {
        return;
    }
    DecodeRecord& r = m_decodes[m_decodeCount++];
    r.self = this;
    r.push = VisDecodePush{};
    std::memcpy(r.push.viewProj, m_rasterPush.viewProj, sizeof(r.push.viewProj));
    r.push.out = outAddress;
    r.push.scene = m_rasterPush.scene;
    r.push.vis = m_desc.bindless->shaderHandle(m_targets.visStorage);
    r.push.width = m_width;
    r.push.height = m_height;
    rg::PassBuilder pass = graph.addPass("vis.decode", &VisBuffer::recordDecode, &r);
    pass.use(refs.vis, rg::Access::StorageRead, {}, rg::kStageCompute);
    gpu_scene::GpuScene::useAll(pass, scene, rg::Access::StorageRead, rg::kStageCompute);
    if (scene.indices.valid()) {
        pass.use(scene.indices, rg::Access::StorageRead, {}, rg::kStageCompute);
    }
    pass.use(out, rg::Access::StorageWrite, rg::BufferRange{0, static_cast<u64>(m_width) * m_height * sizeof(VisDecodeTexel)},
             rg::kStageCompute);
}

void VisBuffer::recordDraw(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const DrawRecord& r = *static_cast<const DrawRecord*>(user);
    const VisBuffer& self = *r.self;
    const bool atomic = self.m_desc.mode == VisMode::Atomic64;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    VkRenderingAttachmentInfo color{};
    color.sType = VK_STRUCTURE_TYPE_RENDERING_ATTACHMENT_INFO;
    VkRenderingAttachmentInfo depth{};
    depth.sType = VK_STRUCTURE_TYPE_RENDERING_ATTACHMENT_INFO;
    VkRenderingInfo rendering{};
    rendering.sType = VK_STRUCTURE_TYPE_RENDERING_INFO;
    rendering.renderArea.extent = {self.m_width, self.m_height};
    rendering.layerCount = 1;
    if (!atomic) {
        color.imageView = static_cast<VkImageView>(context.imageView(r.vis));
        color.imageLayout = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL;
        color.loadOp = r.clear ? VK_ATTACHMENT_LOAD_OP_CLEAR : VK_ATTACHMENT_LOAD_OP_LOAD;
        color.storeOp = VK_ATTACHMENT_STORE_OP_STORE;
        color.clearValue.color.uint32[0] = kVisInvalid;
        color.clearValue.color.uint32[1] = kVisInvalid;
        depth.imageView = static_cast<VkImageView>(context.imageView(r.depth));
        depth.imageLayout = VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL;
        depth.loadOp = r.clear ? VK_ATTACHMENT_LOAD_OP_CLEAR : VK_ATTACHMENT_LOAD_OP_LOAD;
        depth.storeOp = VK_ATTACHMENT_STORE_OP_STORE;
        depth.clearValue.depthStencil.depth = 1.f;
        rendering.colorAttachmentCount = 1;
        rendering.pColorAttachments = &color;
        rendering.pDepthAttachment = &depth;
    }
    vkCmdBeginRendering(cmd, &rendering);
    if (r.indices.valid()) {
        const VkPipelineLayout layout = static_cast<VkPipelineLayout>(self.m_graphicsLayout);
        vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS,
                          static_cast<VkPipeline>(atomic ? self.m_atomicPipeline : self.m_rasterPipeline));
        self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, self.m_graphicsLayout, 0);
        const VkViewport viewport{0.f, 0.f, static_cast<f32>(self.m_width), static_cast<f32>(self.m_height), 0.f, 1.f};
        const VkRect2D scissor{{0, 0}, {self.m_width, self.m_height}};
        vkCmdSetViewport(cmd, 0, 1, &viewport);
        vkCmdSetScissor(cmd, 0, 1, &scissor);
        vkCmdBindIndexBuffer(cmd, static_cast<VkBuffer>(context.buffer(r.indices)), 0, VK_INDEX_TYPE_UINT32);
        vkCmdPushConstants(cmd, layout, VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, 0, sizeof(VisRasterPush),
                           &self.m_rasterPush);
        r.culler->recordDraws(cmd, r.phase);
    }
    vkCmdEndRendering(cmd);
#else
    (void)context;
    (void)user;
#endif
}

void VisBuffer::recordVis64(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const Vis64Record& r = *static_cast<const Vis64Record*>(user);
    const VisBuffer& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_vis64Pipeline));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_computeLayout, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_computeLayout), VK_SHADER_STAGE_COMPUTE_BIT, 0,
                       sizeof(Vis64Push), &r.push);
    vkCmdDispatch(cmd, (r.push.width + kGroup - 1u) / kGroup, (r.push.height + kGroup - 1u) / kGroup, 1);
#else
    (void)context;
    (void)user;
#endif
}

void VisBuffer::recordDecode(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const DecodeRecord& r = *static_cast<const DecodeRecord*>(user);
    const VisBuffer& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_decodePipeline));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_computeLayout, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_computeLayout), VK_SHADER_STAGE_COMPUTE_BIT, 0,
                       sizeof(VisDecodePush), &r.push);
    vkCmdDispatch(cmd, (r.push.width + kGroup - 1u) / kGroup, (r.push.height + kGroup - 1u) / kGroup, 1);
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::visbuffer
